    class OnCurveError < Error; end

    PDA_MARKER = 'ProgramDerivedAddress'
    MAX_SEEDS = 16
    MAX_SEED_LENGTH = 32

    # ed25519 curve constants (RFC 8032).
    ED25519_P = (2**255) - 19
    ED25519_D = ((ED25519_P - 121_665) * 121_666.pow(ED25519_P - 2, ED25519_P)) % ED25519_P
    ED25519_SQRT_M1 = 2.pow((ED25519_P - 1) / 4, ED25519_P)

    # Derives a program address from the given seeds. Raises OnCurveError if
    # the resulting address lies on the ed25519 curve.
    def self.create_program_address(seeds, program_id)
