      data = +''.b
      seeds.each do |seed|
        seed = seed.to_s.b
        raise Error, "payment_channels: seed too long (max #{MAX_SEED_LENGTH} bytes)" if seed.bytesize > MAX_SEED_LENGTH

        data << seed
