    # Returns true when the given 32 bytes are a valid ed25519 point encoding,
    # following the decoding procedure of RFC 8032 section 5.1.3.
    def self.on_curve?(bytes)
      bytes = bytes.to_s.b
      return false unless bytes.bytesize == 32

      encoded = bytes.bytes
      sign = encoded[31] >> 7
      encoded[31] &= 0x7F
      y = 0
      encoded.reverse_each { |byte| y = (y << 8) | byte }
      return false if y >= ED25519_P

      p = ED25519_P
      y2 = y.pow(2, p)
      u = (y2 - 1) % p
      v = ((ED25519_D * y2) + 1) % p

      # Candidate square root x of u/v: x = u * v^3 * (u * v^7)^((p - 5) / 8).
      x = (u * v.pow(3, p) % p) * (u * v.pow(7, p) % p).pow((p - 5) / 8, p) % p
